// split_decls_integration.rs - Integrate split-decls approach with dependency extraction
// Generated by step4_bootstrap - Split Decls Integration

use std::fs;
use std::path::{Path, PathBuf};
use syn::{File, Item};
use quote::ToTokens;
use walkdir::WalkDir;
use anyhow::Result;

pub fn find_rust_files_in_dependency(dep_path: &str) -> Vec<PathBuf> {
    let path = Path::new(dep_path);
    if !path.exists() {
        // Try alternative paths
        let alt_paths = vec![
            format!("../{}", dep_path.trim_start_matches("../")),
            format!("../../{}", dep_path.trim_start_matches("../../")),
            dep_path.replace("../../rust/compiler/", "../rust/compiler/"),
            dep_path.replace("../rust/compiler/", "../../rust/compiler/"),
        ];
        
        for alt_path in alt_paths {
            let alt = Path::new(&alt_path);
            if alt.exists() {
                return find_rust_files_recursive(alt);
            }
        }
        return Vec::new();
    }
    
    find_rust_files_recursive(path)
}

fn find_rust_files_recursive(path: &Path) -> Vec<PathBuf> {
    WalkDir::new(path)
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| {
            let path = e.path();
            path.extension().map_or(false, |ext| ext == "rs") &&
            !path.to_string_lossy().contains("target/") &&
            !path.to_string_lossy().contains(".git/") &&
            !path.to_string_lossy().contains("tests/") // Skip test files for now
        })
        .map(|e| e.path().to_path_buf())
        .collect()
}

pub fn extract_declarations_from_file(file_path: &Path) -> Result<Vec<String>> {
    let content = fs::read_to_string(file_path)?;
    let parsed: File = syn::parse_file(&content)?;
    
    let mut declarations = Vec::new();
    
    for (i, item) in parsed.items.iter().enumerate() {
        let (decl_type, name) = match item {
            Item::Fn(f) => ("fn", f.sig.ident.to_string()),
            Item::Struct(s) => ("struct", s.ident.to_string()),
            Item::Enum(e) => ("enum", e.ident.to_string()),
            Item::Trait(t) => ("trait", t.ident.to_string()),
            Item::Impl(_) => ("impl", format!("impl_{}", i)),
            Item::Const(c) => ("const", c.ident.to_string()),
            Item::Static(s) => ("static", s.ident.to_string()),
            Item::Type(t) => ("type", t.ident.to_string()),
            Item::Union(u) => ("union", u.ident.to_string()),
            _ => continue,
        };
        
        let wrapped_decl = format!("mkdecl{}!({})", decl_type, name);
        declarations.push(wrapped_decl);
    }
    
    Ok(declarations)
}

pub fn extract_all_declarations_from_dependency(dep_path: &str) -> Result<Vec<String>> {
    let rust_files = find_rust_files_in_dependency(dep_path);
    let mut all_declarations = Vec::new();
    
    for file in rust_files {
        if let Ok(declarations) = extract_declarations_from_file(&file) {
            all_declarations.extend(declarations);
        }
    }
    
    Ok(all_declarations)
}

#[macro_export]
macro_rules! mkdep_split_decls {
    ($dep_path:expr) => {{
        extract_all_declarations_from_dependency($dep_path).unwrap_or_default()
    }};
}

#[macro_export]
macro_rules! mkrustc_full_split {
    () => {{
        let rustc_deps = mkfull_dep_tree!("rustc");
        let mut all_decls = Vec::new();
        
        println!("🔍 Extracting split-decls from rustc dependencies...");
        for dep in rustc_deps {
            println!("  📦 Processing {} at {}", dep.name, dep.path);
            let decls = mkdep_split_decls!(&dep.path);
            println!("    ✅ Found {} declarations", decls.len());
            all_decls.extend(decls);
        }
        
        println!("🎯 Total rustc declarations: {}", all_decls.len());
        all_decls
    }};
}
